#!/usr/bin/env bash
# protect_sensor.sh - put one ESP32 under the on-chain access check (v8).
#
# Run in WSL on the publisher machine (it holds PolicyAdminCap and IssuerCap),
# from the repo root. All ids come from deploy/v8/env.v8.sh (generated by
# scripts/v8/03_gen_config.sh); nothing is hard-coded.
#
#   esp32/das/protect_sensor.sh <device> <reader-originator> [node ...]
#   esp32/das/protect_sensor.sh esp32-dht-01 Cesp32-reader-01      (every active node)
#
# Nodes and their addresses come from deploy/inventory.tsv.
#
# What it does
#   1. policy::set_policy  resource /in-cse/C<device>, min_trust = POLICY_MIN_TRUST, mask READ (1)
#   2. cap_token::mint     one READ token PER NODE, owned by that node's address
#   3. prints, per node, the two sui.mappings.properties lines its DAS needs
#
# Why these values
#   - The device is an AE created by the bridge with originator C<device>, so
#     its resource id is /in-cse/C<device> on EVERY node, and that is what
#     OM2M's DynamicAuthorizationSelector sends the DAS (targetedResourceID).
#   - The DAS signs as the node it runs on (v8 A3/A4: requester = signer =
#     token owner). Data lives on whichever node is PARENT, and the parent can
#     change, so every node that can become parent needs its own token.
#   - READ only: an ordinary RETRIEVE maps to OP_READ (1); DELETE (OP_DELETE)
#     is then refused by cap_token::E_OP_NOT_ALLOWED - found by the DAS's free
#     simulation and never submitted (F3), so a denial costs no gas.
#
# v9: once the quorum council holds PolicyAdminCap and IssuerCap, the
# publisher no longer owns them, so these direct calls fail; steps 1-2 then
# become council proposals (scripts/v9, V9_DESIGN.md). Step 3 is unchanged.
set -euo pipefail
DEV=${1:?device}; READER=${2:?reader originator (must start with C, and not be C<device>)}; shift 2
NODES=${*:-}
[[ "$READER" == C* && "$READER" != "C$DEV" ]] || { echo "reader must start with C and differ from C$DEV"; exit 1; }
REPO=$(cd "$(dirname "$0")/../.." && pwd); cd "$REPO"
[[ -f deploy/v8/env.v8.sh ]] || { echo "deploy/v8/env.v8.sh missing: run scripts/v8/03_gen_config.sh"; exit 1; }
# shellcheck disable=SC1091
source deploy/v8/env.v8.sh
REPO=$PWD
# shellcheck disable=SC1091
. scripts/lib/inventory.sh
inv_load
[[ -n "$NODES" ]] || NODES=$(inv_nodes active | tr '\n' ' ')
: "${PKG_V8:?}"; : "${POLICY_REG:?}"; : "${POL_ADMIN_CAP:?}"; : "${ISSUER_CAP:?}"
PKG=${PKG_CALL:-$PKG_V8}
MIN=${POLICY_MIN_TRUST:-50}; GAS=${GAS:-20000000}; DAYS=${DAYS:-30}
RID="/in-cse/C$DEV"
addr_of() { inv_require "$1"; echo "${INV_ADDR[$1]}"; }

echo "package $PKG   resource $RID   reader $READER   nodes: $NODES"
for n in $NODES; do [[ -n "$(addr_of "$n")" ]] || { echo "$n has no sui_address in deploy/inventory.tsv (not onboarded)"; exit 1; }; done

json_status() { python3 -c 'import json,sys;d=json.load(sys.stdin);print(d["effects"]["status"]["status"], d["digest"])'; }

echo "== 1. policy::set_policy"
sui client call --package "$PKG" --module policy --function set_policy \
  --args "$POL_ADMIN_CAP" "$POLICY_REG" "\"$RID\"" "$MIN" 1 --gas-budget "$GAS" --json | json_status

EXPIRY=$(( ($(date +%s) + DAYS*24*3600) * 1000 ))
declare -A TOK
for n in $NODES; do
  echo "== 2. cap_token::mint READ for $n ($(addr_of "$n" | cut -c1-12)...)"
  OUT=$(sui client call --package "$PKG" --module cap_token --function mint \
        --args "$ISSUER_CAP" "$(addr_of "$n")" "\"$RID\"" 1 "$EXPIRY" 100000 --gas-budget "$GAS" --json)
  echo "$OUT" | json_status
  TOK[$n]=$(echo "$OUT" | python3 -c 'import json,sys
d=json.load(sys.stdin)
print(next(c["objectId"] for c in d["objectChanges"] if c.get("type")=="created" and c["objectType"].endswith("::cap_token::CapToken")))')
done

echo
echo "== 3. mapping lines. Add to BOTH ~/sui-runtime-config/sui.mappings.properties and"
echo "   /tmp/sui.mappings.properties on each node, then recreate om2m-active through"
echo "   scripts/v8/04_cutover.sh (mappings are read once, at plugin start). Keep the"
echo "   backslashes: java.util.Properties splits keys on an unescaped ':'."
for n in $NODES; do
  echo
  echo "# --- $n"
  echo "addr.$READER=$(addr_of "$n")"
  echo "token.$READER\\:\\:$RID=${TOK[$n]}"
done
